import{_ as d,o as a,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Сводная таблица деления эпох","description":"","frontmatter":{},"headers":[],"relativePath":"ru/70-纪元划分总表.md","filePath":"ru/70-纪元划分总表.md"}'),i={name:"ru/70-纪元划分总表.md"};function l(h,t,o,n,s,b){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="сводная-таблица-деления-эпох" tabindex="-1">Сводная таблица деления эпох <a class="header-anchor" href="#сводная-таблица-деления-эпох" aria-label="Permalink to &quot;Сводная таблица деления эпох&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>№ документа</td><td>70</td></tr><tr><td>Модуль</td><td>Исторические эпохи и крупные события</td></tr><tr><td>Ключевые слова</td><td>Деление эпох, историческая периодизация, четырёхэтапное повышение измерения, хронология, вехи</td></tr></tbody></table><h2 id="i-основные-принципы-деления-эпох" tabindex="-1">I. Основные принципы деления эпох <a class="header-anchor" href="#i-основные-принципы-деления-эпох" aria-label="Permalink to &quot;I. Основные принципы деления эпох&quot;">​</a></h2><p>Деление исторических эпох Вселенной Хэнъюань принимает путь четырёхэтапного повышения измерения как основополагающую рамку, а состояние развития механизма Якоря — как центральное основание периодизации. Каждая эпоха соответствует коренному преобразованию отношений между цивилизацией и вселенной; границы между эпохами — не произвольные точки времени, а отмечены крупными событиями вселенского значения.</p><p>Деление эпох следует трём принципам:</p><ul><li><strong>Принцип соответствия повышению измерения</strong>: каждая большая эпоха соответствует одному этапу пути четырёхэтапного повышения измерения, а подпериоды внутри эпохи соответствуют ключевым достижениям этого этапа.</li><li><strong>Принцип маркировки событиями</strong>: точки начала и конца эпохи определяются знаковыми крупными событиями, а не простым равным делением времени.</li><li><strong>Принцип состояния цивилизации</strong>: каждая эпоха называется по центральным особенностям цивилизации этого периода, отражая главные противоречия и направление развития того времени.</li></ul><h2 id="ii-сводная-таблица-исторических-эпох-вселеннои-хэнъюань" tabindex="-1">II. Сводная таблица исторических эпох Вселенной Хэнъюань <a class="header-anchor" href="#ii-сводная-таблица-исторических-эпох-вселеннои-хэнъюань" aria-label="Permalink to &quot;II. Сводная таблица исторических эпох Вселенной Хэнъюань&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№ эпохи</th><th>Название эпохи</th><th>Соответствующий этап повышения</th><th>События-маркеры границ</th><th>Центральные особенности</th></tr></thead><tbody><tr><td>Первая эпоха</td><td>Эпоха до Якоря</td><td>До повышения измерения</td><td>Рождение вселенной → пробуждение первого поколения Якорей</td><td>Хищническая культивация доминирует, частые разрывы цивилизаций</td></tr><tr><td>Вторая эпоха</td><td>Эпоха Пробуждения Якоря</td><td>Запуск закладки фундамента реальности</td><td>Пробуждение Якорей первого поколения → подписание Симбиотической Хартии</td><td>Установлен механизм Якоря, зарождение антихищнической мысли</td></tr><tr><td>Третья эпоха</td><td>Период Установления Симбиотической Системы</td><td>Закладка фундамента реальности</td><td>Подписание Симбиотической Хартии → полное открытие Трёхсот Систем</td><td>Симбиотические институты внедрены, социальная реконструкция завершена</td></tr><tr><td>Четвёртая эпоха</td><td>Эпоха Открытия и Активации Систем</td><td>Запуск технологического усиления</td><td>Открытие Трёхсот Систем → завершение Стратегии активации 20 %</td><td>Культивация популяризирована, прорывы инженерии законов</td></tr><tr><td>Пятая эпоха</td><td>Эпоха Первого Повышения Измерения</td><td>Технологическое усиление → эволюция сознания</td><td>Успех первого повышения измерения → основание Республики Десяти Тысяч Рас</td><td>Повышение измерения цивилизации подтверждено, прорыв интерфейса домена сознания</td></tr><tr><td>Шестая эпоха</td><td>Эпоха Республики Десяти Тысяч Рас</td><td>Эволюция сознания</td><td>Основание Республики Десяти Тысяч Рас → запуск межплоскостных исследований</td><td>Унификация институтов рас, симбиоз коллективного сознания</td></tr><tr><td>Седьмая эпоха</td><td>Эпоха Межплоскостных Исследований</td><td>Эволюция сознания → межзвёздный симбиоз</td><td>Запуск межплоскостных исследований → предварительное завершение межзвёздной сети</td><td>Великие открытия плоскостей, расширение сети Якорей</td></tr><tr><td>Восьмая эпоха</td><td>Эпоха Межзвёздного Симбиоза</td><td>Межзвёздный симбиоз</td><td>Завершение межзвёздной сети → общее повышение измерения вселенной</td><td>Вселенский симбиоз рас, повышение измерения вселенной в процессе</td></tr></tbody></table><h2 id="iii-временные-рамки-и-ключевые-показатели-каждои-эпохи" tabindex="-1">III. Временные рамки и ключевые показатели каждой эпохи <a class="header-anchor" href="#iii-временные-рамки-и-ключевые-показатели-каждои-эпохи" aria-label="Permalink to &quot;III. Временные рамки и ключевые показатели каждой эпохи&quot;">​</a></h2><p>Поскольку Вселенная Хэнъюань содержит множество плоскостей, скорость течения времени различается между плоскостями; временные рамки эпох основаны на стандартном времени главной плоскости:</p><table tabindex="0"><thead><tr><th>Эпоха</th><th>Ориентировочные рамки</th><th>Охват Якоря</th><th>Доля культиваторов</th><th>Индекс Симбиоза</th></tr></thead><tbody><tr><td>Эпоха до Якоря</td><td>Неустановимо (порядка миллиардов лет)</td><td>0 %</td><td>&lt;0,01 %</td><td>&lt;10</td></tr><tr><td>Эпоха Пробуждения Якоря</td><td>Несколько тысячелетий</td><td>1 %→10 %</td><td>0,01 %→1 %</td><td>10→30</td></tr><tr><td>Период Установления Симбиотической Системы</td><td>Несколько столетий</td><td>10 %→40 %</td><td>1 %→10 %</td><td>30→50</td></tr><tr><td>Эпоха Открытия и Активации Систем</td><td>Несколько столетий</td><td>40 %→70 %</td><td>10 %→30 %</td><td>50→70</td></tr><tr><td>Эпоха Первого Повышения Измерения</td><td>Несколько десятилетий</td><td>70 %→85 %</td><td>30 %→50 %</td><td>70→80</td></tr><tr><td>Эпоха Республики Десяти Тысяч Рас</td><td>Несколько столетий</td><td>85 %→95 %</td><td>50 %→70 %</td><td>80→90</td></tr><tr><td>Эпоха Межплоскостных Исследований</td><td>Несколько тысячелетий</td><td>95 %→99 %</td><td>70 %→90 %</td><td>90→95</td></tr><tr><td>Эпоха Межзвёздного Симбиоза</td><td>Продолжается</td><td>→100 %</td><td>→100 %</td><td>→100</td></tr></tbody></table><p>Охват Якоря означает долю подрегионов плоскостей, где развёрнуто аппаратное обеспечение Якоря; доля культиваторов означает долю форм жизни, охваченных официальными системами культивации; Индекс Симбиоза — комплексный показатель, измеряющий степень симбиоза цивилизации, с максимальным баллом 100.</p><h2 id="iv-внутренняя-логика-эволюции-эпох" tabindex="-1">IV. Внутренняя логика эволюции эпох <a class="header-anchor" href="#iv-внутренняя-логика-эволюции-эпох" aria-label="Permalink to &quot;IV. Внутренняя логика эволюции эпох&quot;">​</a></h2><p>Эволюция эпох Вселенной Хэнъюань — не линейное течение времени, а спирально восходящий эволюционный процесс. Каждая эпоха, разрешая центральные противоречия, оставленные предыдущей, одновременно взращивает условия развития следующей:</p><ul><li>Фундаментальное противоречие Эпохи до Якоря — противоречие между хищничеством и симбиозом, чьё крайнее развитие привело к неизбежности пробуждения Якоря.</li><li>Эпоха Пробуждения Якоря разрешила вопрос «существуют ли Якоря», но столкнулась с институциональным вызовом «кому служат Якоря».</li><li>Период Установления Симбиотической Системы завершил институциональное строительство, но монополия на ресурсы культивации всё ещё сдерживала эволюцию масс.</li><li>Эпоха Открытия и Активации Систем сломала монополию культивации, но скачок индивидуальных способностей принёс новые этические и безопасностные вызовы.</li><li>Эпоха Первого Повышения Измерения подтвердила осуществимость повышения, но повышение одной плоскости недостаточно для движения общей эволюции вселенной.</li><li>Эпоха Республики Десяти Тысяч Рас унифицировала институты цивилизации, но во вселенной оставалось множество неконтактированных плоскостей и рас.</li><li>Эпоха Межплоскостных Исследований расширила границы цивилизации, но разрозненные плоскости нуждались в более тесных межзвёздных связях.</li><li>Эпоха Межзвёздного Симбиоза в конечном счёте указывает на конечную цель общего повышения измерения вселенной.</li></ul><h2 id="v-позиционирование-текущеи-эпохи" tabindex="-1">V. Позиционирование текущей эпохи <a class="header-anchor" href="#v-позиционирование-текущеи-эпохи" aria-label="Permalink to &quot;V. Позиционирование текущей эпохи&quot;">​</a></h2><p>Согласно текущему состоянию развития Вселенной Хэнъюань, цивилизация находится на критическом рубеже перехода от Третьей эпохи (Период Установления Симбиотической Системы) к Четвёртой эпохе (Эпоха Открытия и Активации Систем). Симбиотические институты внедрены в главных плоскостях, работа по открытию Трёхсот Систем всесторонне продвигается, и Стратегия активации 20 % вступила в фазу реализации. Множество ключевых технологий слоя инженерии законов (Двигатель Дедукции Плода Множителя, устройства регулирования пространственных правовых принципов, Система Зеркала Репликации) перешли из лаборатории в массовое производство.</p><p>Центральная задача этого переходного периода: обеспечить, чтобы открытие Трёхсот Систем действительно принесло пользу всем формам жизни, одновременно готовя первую группу Верховных Силачей Плоскости через Стратегию активации 20 %, накапливая достаточно энергии и опыта для первого повышения измерения.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Сводная таблица деления эпох — макрорамка понимания исторической эволюции Вселенной Хэнъюань. Она сжимает долгую историю вселенной в восемь эпох с ясной внутренней логикой, каждая эпоха — необходимая ступень к общему повышению измерения вселенной. Последующие документы подробно развернут каждую эпоху и крупные события в ней.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>71-前锚点时代 (Эпоха до Якоря)</li><li>72-锚点觉醒纪元 (Эпоха Пробуждения Якоря)</li><li>76-首次升维里程碑 (Веха первого повышения измерения)</li></ul>',22)])])}const _=d(i,[["render",l]]);export{c as __pageData,_ as default};
